source("R/setup.R")

suppressPackageStartupMessages({
  library(tseries)  # adf.test
  library(urca)     # ur.kpss, ca.jo
  library(vars)     # VARselect, VAR, causality, irf, fevd
})

umc_ts &lt;- read_monthly_ts("data/umcsent.csv")

fmt_p &lt;- function(p) {
  if (p &lt; 2.2e-16) return("&lt; 2.2e-16")
  if (p &lt; 0.001) return(paste("=", format(p, digits = 3, scientific = TRUE)))
  paste("=", sprintf("%.4f", p))
}

# Johansen test statistics next to their critical values
johansen_table &lt;- function(jo) {
  data.frame(
    Hypothesis = rownames(jo@cval),
    Statistic = round(jo@teststat, 2),
    jo@cval,
    check.names = FALSE,
    row.names = NULL
  )
}
The second series is the University of Michigan Index of Consumer Sentiment (UMCSENT), a monthly survey of how US households see current and future economic conditions. The question is whether consumer sentiment carries information about future industrial production.
